WITH metrics AS (SELECT *, CORR(stock_qty, price) OVER (PARTITION BY category) corr_stock_qty_price, LEAD(stock_qty, 2) OVER (PARTITION BY category ORDER BY cost, id) next_stock_qty, LEAD(stock_qty, 2) OVER (PARTITION BY category, supplier_id ORDER BY stock_qty, id) next_stock_qty_2 FROM products) SELECT s.id, s.brand, s.price, s.stock_qty, s.launch_date, s.supplier_id, s.corr_stock_qty_price, s.next_stock_qty, s.next_stock_qty_2, CASE WHEN brand RLIKE '^(Stark|Initech)$' THEN 'OTHER_ZONE' WHEN brand RLIKE '^(Acme|Globex)$' THEN 'PRIORITY' ELSE 'EXTENDED' END AS brand_zone, (SELECT MIN(t2.cost) FROM products t2 WHERE t2.supplier_id = s.supplier_id) AS min_product_cost FROM metrics s
